CREATE TABLE IF NOT EXISTS practice_sessions (user_id uuid PRIMARY KEY REFERENCES users(id), answer jsonb NOT NULL DEFAULT '{}', version bigint NOT NULL DEFAULT 0, checks jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incident_reviews (event_id uuid PRIMARY KEY REFERENCES audit_events(id), reviewer_id uuid NOT NULL REFERENCES users(id), note text NOT NULL, reviewed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS appeals (id uuid PRIMARY KEY, event_id uuid UNIQUE NOT NULL REFERENCES audit_events(id), attempt_id uuid NOT NULL REFERENCES attempts(id), user_id uuid NOT NULL REFERENCES users(id), status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','UNDER_REVIEW','UPHELD','DISMISSED')), version int NOT NULL DEFAULT 1, reopened boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS appeal_messages (id uuid PRIMARY KEY, appeal_id uuid NOT NULL REFERENCES appeals(id), author_id uuid NOT NULL REFERENCES users(id), message text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS appeals_user_idx ON appeals(user_id,updated_at);
CREATE TABLE IF NOT EXISTS sso_identities (issuer text NOT NULL, subject text NOT NULL, user_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(issuer,subject), UNIQUE(issuer,user_id));
CREATE TABLE IF NOT EXISTS lms_course_links (course_id uuid PRIMARY KEY REFERENCES courses(id), external_id text UNIQUE NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lms_exam_links (exam_id uuid PRIMARY KEY REFERENCES exams(id), external_id text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lms_users (external_id text PRIMARY KEY, user_id uuid UNIQUE NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS integration_runs (id uuid PRIMARY KEY, actor_id uuid NOT NULL REFERENCES users(id), kind text NOT NULL CHECK(kind IN('ROSTER','GRADES')), target_id uuid NOT NULL, status text NOT NULL DEFAULT 'PREVIEW' CHECK(status IN('PREVIEW','RUNNING','COMPLETE','PARTIAL','FAILED')), preview jsonb NOT NULL, result jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS integration_runs_created ON integration_runs(created_at DESC);
